import{_ as a,o as r,c as l,a0 as o}from"./chunks/framework.DCluYYrN.js";const c=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"ru_RU/guide/faq.md","filePath":"ru_RU/guide/faq.md"}'),n={name:"ru_RU/guide/faq.md"};function t(s,e,i,d,h,u){return r(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="поддерживает-ли-kernelsu-мое-устроиство" tabindex="-1">Поддерживает ли KernelSU мое устройство? <a class="header-anchor" href="#поддерживает-ли-kernelsu-мое-устроиство" aria-label="Permalink to &quot;Поддерживает ли KernelSU мое устройство?&quot;">​</a></h2><p>KernelSU поддерживает устройства под управлением Android с разблокированным загрузчиком. Однако официальная поддержка предоставляется только для GKI Linux Kernel 5.10+ (на практике это означает, что ваше устройство должно иметь Android 12 из коробки для поддержки).</p><p>Вы можете легко проверить поддержку вашего устройства через менеджер KernelSU, который доступен <a href="https://github.com/tiann/KernelSU/releases" target="_blank" rel="noreferrer">здесь</a>.</p><p>Если приложение показывает <code>Not installed</code>, значит ваше устройство официально поддерживается KernelSU.</p><p>Если приложение показывает <code>Unsupported</code>, значит ваше устройство в настоящее время не поддерживается официально. Однако вы можете собрать исходный код ядра и интегрировать KernelSU, чтобы заставить его работать, или использовать <a href="./unofficially-support-devices.html">Неофициально поддерживаемые устройства</a>.</p><h2 id="нужно-ли-для-kernelsu-разблокировать-загрузчик" tabindex="-1">Нужно ли для KernelSU разблокировать загрузчик? <a class="header-anchor" href="#нужно-ли-для-kernelsu-разблокировать-загрузчик" aria-label="Permalink to &quot;Нужно ли для KernelSU разблокировать загрузчик?&quot;">​</a></h2><p>Безусловно, да.</p><h2 id="поддерживает-ли-kernelsu-модули" tabindex="-1">Поддерживает ли KernelSU модули? <a class="header-anchor" href="#поддерживает-ли-kernelsu-модули" aria-label="Permalink to &quot;Поддерживает ли KernelSU модули?&quot;">​</a></h2><p>Да, большинство модулей Magisk работают с KernelSU. Однако, если вашему модулю нужно модифицировать файлы <code>/system</code>, вам необходимо установить <a href="./metamodule.html">метамодуль</a> (например, <code>meta-overlayfs</code>). Другие функции модулей работают без метамодуля. Проверьте <a href="./module.html">Руководство по модулям</a> для получения дополнительной информации.</p><h2 id="поддерживает-ли-kernelsu-xposed" tabindex="-1">Поддерживает ли KernelSU Xposed? <a class="header-anchor" href="#поддерживает-ли-kernelsu-xposed" aria-label="Permalink to &quot;Поддерживает ли KernelSU Xposed?&quot;">​</a></h2><p>Да, вы можете использовать LSPosed (или другие современные производные Xposed) с <a href="https://github.com/Dr-TSNG/ZygiskNext" target="_blank" rel="noreferrer">ZygiskNext</a>.</p><h2 id="поддерживает-ли-kernelsu-zygisk" tabindex="-1">Поддерживает ли KernelSU Zygisk? <a class="header-anchor" href="#поддерживает-ли-kernelsu-zygisk" aria-label="Permalink to &quot;Поддерживает ли KernelSU Zygisk?&quot;">​</a></h2><p>KernelSU не имеет встроенной поддержки Zygisk, но вы можете использовать модуль типа <a href="https://github.com/Dr-TSNG/ZygiskNext" target="_blank" rel="noreferrer">ZygiskNext</a> для его поддержки.</p><h2 id="совместим-ли-kernelsu-с-magisk" tabindex="-1">Совместим ли KernelSU с Magisk? <a class="header-anchor" href="#совместим-ли-kernelsu-с-magisk" aria-label="Permalink to &quot;Совместим ли KernelSU с Magisk?&quot;">​</a></h2><p>Система модулей KernelSU конфликтует с магическим монтированием Magisk. Если в KernelSU включен какой-либо модуль, Magisk полностью перестанет работать.</p><p>Однако, если вы используете только <code>su</code> из KernelSU, он будет хорошо работать с Magisk. KernelSU модифицирует <code>kernel</code>, а Magisk модифицирует <code>ramdisk</code>, позволяя обоим работать вместе.</p><h2 id="заменит-ли-kernelsu-magisk" tabindex="-1">Заменит ли KernelSU Magisk? <a class="header-anchor" href="#заменит-ли-kernelsu-magisk" aria-label="Permalink to &quot;Заменит ли KernelSU Magisk?&quot;">​</a></h2><p>Мы считаем, что нет, и это не наша цель. Magisk достаточно хорош для решения root в пользовательском пространстве и будет жить долго. Цель KernelSU - предоставить пользователям интерфейс ядра, а не заменить Magisk.</p><h2 id="может-ли-kernelsu-поддерживать-устроиства-не-относящиеся-к-gki" tabindex="-1">Может ли KernelSU поддерживать устройства, не относящиеся к GKI? <a class="header-anchor" href="#может-ли-kernelsu-поддерживать-устроиства-не-относящиеся-к-gki" aria-label="Permalink to &quot;Может ли KernelSU поддерживать устройства, не относящиеся к GKI?&quot;">​</a></h2><p>Это возможно. Но вам нужно скачать исходный код ядра и интегрировать KernelSU в дерево исходных текстов и скомпилировать ядро самостоятельно.</p><h2 id="может-ли-kernelsu-поддерживать-устроиства-ниже-android-12" tabindex="-1">Может ли KernelSU поддерживать устройства ниже Android 12? <a class="header-anchor" href="#может-ли-kernelsu-поддерживать-устроиства-ниже-android-12" aria-label="Permalink to &quot;Может ли KernelSU поддерживать устройства ниже Android 12?&quot;">​</a></h2><p>Это ядро устройства влияет на совместимость KernelSU, и это не имеет ничего общего с версией Android. Единственное ограничение заключается в том, что устройства, выпущенные с Android 12, должны иметь версию ядра 5.10+ (устройства GKI). Итак:</p><ol><li>Устройства, выпущенные с Android 12, должны поддерживаться.</li><li>Устройства со старым ядром (некоторые устройства с Android 12 также имеют старое ядро) совместимы (вам нужно самостоятельно собрать ядро).</li></ol><h2 id="может-ли-kernelsu-поддерживать-старое-ядро" tabindex="-1">Может ли KernelSU поддерживать старое ядро? <a class="header-anchor" href="#может-ли-kernelsu-поддерживать-старое-ядро" aria-label="Permalink to &quot;Может ли KernelSU поддерживать старое ядро?&quot;">​</a></h2><p>Это возможно. KernelSU теперь бэкпортирован на ядро 4.14. Для более старых ядер вам нужно выполнить бэкпорт вручную, и PR приветствуются!</p><h2 id="как-интегрировать-kernelsu-для-старого-ядра" tabindex="-1">Как интегрировать KernelSU для старого ядра? <a class="header-anchor" href="#как-интегрировать-kernelsu-для-старого-ядра" aria-label="Permalink to &quot;Как интегрировать KernelSU для старого ядра?&quot;">​</a></h2><p>Пожалуйста, ознакомьтесь с руководством <a href="./how-to-integrate-for-non-gki.html">Интеграция для устройств не-GKI</a>.</p><h2 id="почему-моя-версия-android-13-а-ядро-показывает-android12-5-10" tabindex="-1">Почему моя версия Android - 13, а ядро показывает &quot;android12-5.10&quot;? <a class="header-anchor" href="#почему-моя-версия-android-13-а-ядро-показывает-android12-5-10" aria-label="Permalink to &quot;Почему моя версия Android - 13, а ядро показывает &quot;android12-5.10&quot;?&quot;">​</a></h2><p>Версия ядра не имеет ничего общего с версией Android. Если вам нужно прошить ядро, всегда используйте версию ядра; версия Android не так важна.</p><h2 id="я-gki-1-0-могу-ли-я-использовать-это" tabindex="-1">Я GKI 1.0, могу ли я использовать это? <a class="header-anchor" href="#я-gki-1-0-могу-ли-я-использовать-это" aria-label="Permalink to &quot;Я GKI 1.0, могу ли я использовать это?&quot;">​</a></h2><p>GKI 1.0 полностью отличается от GKI 2.0, вы должны скомпилировать ядро самостоятельно.</p><h2 id="как-можно-сделать-system-rw" tabindex="-1">Как можно сделать <code>/system</code> RW? <a class="header-anchor" href="#как-можно-сделать-system-rw" aria-label="Permalink to &quot;Как можно сделать `/system` RW?&quot;">​</a></h2><p>Мы не рекомендуем напрямую модифицировать системный раздел. Пожалуйста, ознакомьтесь с <a href="./module.html">Руководством по модулям</a> для его бессистемной модификации. Если вы настаиваете на этом, проверьте <a href="https://github.com/HuskyDG/magic_overlayfs" target="_blank" rel="noreferrer">magisk_overlayfs</a>.</p><h2 id="может-ли-kernelsu-модифицировать-hosts-как-использовать-adaway" tabindex="-1">Может ли KernelSU модифицировать hosts? Как использовать AdAway? <a class="header-anchor" href="#может-ли-kernelsu-модифицировать-hosts-как-использовать-adaway" aria-label="Permalink to &quot;Может ли KernelSU модифицировать hosts? Как использовать AdAway?&quot;">​</a></h2><p>Конечно. Но KernelSU не имеет встроенной поддержки hosts, вы можете установить модуль типа <a href="https://github.com/symbuzzer/systemless-hosts-KernelSU-module" target="_blank" rel="noreferrer">systemless-hosts</a> для этого.</p><h2 id="почему-мои-модули-не-работают-после-новои-установки" tabindex="-1">Почему мои модули не работают после новой установки? <a class="header-anchor" href="#почему-мои-модули-не-работают-после-новои-установки" aria-label="Permalink to &quot;Почему мои модули не работают после новой установки?&quot;">​</a></h2><p>Если вашим модулям нужно модифицировать файлы <code>/system</code>, вам необходимо установить <a href="./metamodule.html">метамодуль</a> для монтирования директории <code>system</code>. Другие функции модулей (скрипты, sepolicy, system.prop) работают без метамодуля.</p><p><strong>Решение</strong>: См. <a href="./metamodule.html">Руководство по метамодулям</a> для инструкций по установке.</p><h2 id="что-такое-метамодуль-и-зачем-он-мне-нужен" tabindex="-1">Что такое метамодуль и зачем он мне нужен? <a class="header-anchor" href="#что-такое-метамодуль-и-зачем-он-мне-нужен" aria-label="Permalink to &quot;Что такое метамодуль и зачем он мне нужен?&quot;">​</a></h2><p>Метамодуль - это специальный модуль, который предоставляет инфраструктуру для монтирования обычных модулей. См. <a href="./metamodule.html">Руководство по метамодулям</a> для полного объяснения.</p>',41)])])}const p=a(n,[["render",t]]);export{c as __pageData,p as default};
